import fractions

def simplify(r):
    if r == 0:
        return (0, 1)
    return fractions.Fraction(r).limit_denominator()

def get_properties(r):
    r_sim = simplify(r)
    N, D = r_sim.numerator, r_sim.denominator

    # Check if we can find relationships based on the constraints
    props = {
        "N": N, "D": D,
        "Neg_r": simplify(-r),
        "Comp_r": simplify(1 - r),
        "Recip_r": simplify(1 / r)
    }
    return props

targets = [
    fractions.Fraction(7, 3), fractions.Fraction(11, 4), fractions.Fraction(2024, 5), 
    fractions.Fraction(109, 11), fractions.Fraction(3, 71), fractions.Fraction(5, 204)
]

print("--- Target Properties ---")
for i, r in enumerate(targets):
    props = get_properties(r)
    print(f"Target {i+1} ({r}): N={props['N']}, D={props['D']}")

# Check relationships between targets
print("\n--- Cross-Target Checks ---")
for i in range(len(targets)):
    for j in range(i + 1, len(targets)):
        r_i = targets[i]
        r_j = targets[j]

        # Check if r_i = -r_j
        if r_i + r_j == 0:
             print(f"Relationship found: Target {i+1} is the negative of Target {j+1}.")

        # Check if r_i = 1 - r_j
        if r_i + r_j == 1:
             print(f"Relationship found: Target {i+1} is the complement of Target {j+1}.")

        # Check if r_i * r_j = 1
        if r_i * r_j == 1:
             print(f"Relationship found: Target {i+1} is the reciprocal of Target {j+1}.")

def transform(r, transformations):
    r_current = r
    # Iteratively apply transformations until a fixed point, cycle, or target hit (up to 5 steps)
    for i in range(5):
        r_next = None
        for T in transformations:
            # T is a function (e.g., lambda x: 1/(1-x), lambda x: -x, lambda x: 1/x)
            try:
                r_next = T(r_current)
                break
            except ZeroDivisionError:
                # Handle division by zero if applicable, though unlikely for the given inputs
                continue

        if r_next is None:
            break

        if r_next in V:
            return f"Hit target: {r_next}"

        r_current = r_next
    return "No hit within iterations"

V = {11/3, -11/3, -8/3, 3/11}
arguments = [7/3, 11/4, 2024/5, 109/11, 3/71, 5/204]

# Define transformations
T_reciprocal = lambda x: 1/x if x != 0 else None
T_negation = lambda x: -x
T_inv_complement = lambda x: 1/(1-x) if x != 1 else None

all_results = {}

for i, r in enumerate(arguments):
    # Check all three transformations starting from r
    results = []

    # 1. Transformation r -> 1/(1-r)
    r_1 = r
    for j in range(5):
        r_1 = T_inv_complement(r_1)
        if r_1 in V:
            results.append(f"T_inv_complement: Hit target {r_1} in {j+1} steps")
            break
    else:
        results.append("T_inv_complement: No hit")

    # 2. Transformation r -> -r
    r_2 = T_negation(r)
    if r_2 in V:
        results.append(f"T_negation: Hit target {r_2} in 1 step")
    else:
        results.append("T_negation: No hit")

    # 3. Transformation r -> 1/r
    r_3 = T_reciprocal(r)
    if r_3 in V:
        results.append(f"T_reciprocal: Hit target {r_3} in 1 step")
    else:
        results.append("T_reciprocal: No hit")

    all_results[r] = results

for r, res in all_results.items():
    print(f"Argument {r}: {res}")

